-- ============================================================
--  WAREHOUSE HANDLING SYSTEM — DATABASE SUBMISSION
--  Team 07 | OOP & Database Module
-- IM/2024/006
-- IM/2024/030
-- IM/2024/051
-- IM/2024/074
-- IM/2024/092
-- IM/2024/110
--  UPDATED 20 Oct 2026 (15 tables). Changes since the first submission:
--    1. New table Refund (orderId, amount, refundDate, reason, processedBy)
--    2. Reservation.returnedQuantity (running total of units returned)
--    3. User.isActive (a deactivated user cannot log in; users are never deleted)
--    4. Report.generatedAt and Report.content (a report keeps its full text)
--    5. Table WarehouseConfiguration removed (yard capacity is no longer part of the system)
--  The sample data below is unchanged. Only 3 demo users can log in; their real
--  bcrypt passwords are set by running SetupPasswords.java once (see the report).
--
--  Part 1: DDL (database + table creation)
--  Part 2: DML (INSERT data)
-- ============================================================

CREATE DATABASE IF NOT EXISTS warehouse_db;
USE warehouse_db;

-- ── Users ───────────────────────────────────────────────────
CREATE TABLE User (
    userId       INT          AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(100) NOT NULL,
    email        VARCHAR(150) NOT NULL UNIQUE,
    passwordHash VARCHAR(255) NOT NULL,
    role         ENUM('WarehouseOperator','SalesOfficer','WarehouseManager') NOT NULL,
    accessLevel  TINYINT      NOT NULL DEFAULT 1,
    isActive     BOOLEAN      NOT NULL DEFAULT TRUE      -- added: deactivated users cannot log in
);

CREATE TABLE WarehouseOperator (
    userId          INT         PRIMARY KEY,
    assignedYardZone VARCHAR(50),
    FOREIGN KEY (userId) REFERENCES User(userId) ON DELETE CASCADE
);

CREATE TABLE SalesOfficer (
    userId      INT            PRIMARY KEY,
    salesTarget DECIMAL(12,2),
    FOREIGN KEY (userId) REFERENCES User(userId) ON DELETE CASCADE
);

CREATE TABLE WarehouseManager (
    userId INT PRIMARY KEY,
    FOREIGN KEY (userId) REFERENCES User(userId) ON DELETE CASCADE
);

-- ── Product catalogue ───────────────────────────────────────
CREATE TABLE Product (
    productId               INT           AUTO_INCREMENT PRIMARY KEY,
    name                    VARCHAR(100)  NOT NULL,
    category                VARCHAR(80),
    unitPrice               DECIMAL(12,2) NOT NULL,
    defaultCuringDurationDays INT         NOT NULL DEFAULT 0
);

-- ── Production batches ──────────────────────────────────────
CREATE TABLE Batch (
    batchId         INT       AUTO_INCREMENT PRIMARY KEY,
    productId       INT       NOT NULL,
    productionDate  DATE      NOT NULL,
    curingEndDate   DATE      NOT NULL,
    quantity        INT       NOT NULL CHECK (quantity > 0),
    curingStatus    ENUM('Curing','Ready','Depleted') NOT NULL DEFAULT 'Curing',
    FOREIGN KEY (productId) REFERENCES Product(productId)
);

-- ── Stock items ─────────────────────────────────────────────
CREATE TABLE StockItem (
    itemId              INT AUTO_INCREMENT PRIMARY KEY,
    batchId             INT NOT NULL,
    location            VARCHAR(80),
    quantity            INT NOT NULL CHECK (quantity >= 0),
    availabilityStatus  ENUM('Curing','Available','Reserved','Shipped','Damaged') NOT NULL DEFAULT 'Curing',
    FOREIGN KEY (batchId) REFERENCES Batch(batchId)
);

-- ── Ledger (audit trail) ────────────────────────────────────
CREATE TABLE LedgerEntry (
    entryId        INT           AUTO_INCREMENT PRIMARY KEY,
    itemId         INT           NOT NULL,
    userId         INT           NOT NULL,
    actionType     ENUM('Produced','Curing','CuringComplete','Reserved',
                        'Shipped','Damaged','Returned','Adjusted') NOT NULL,
    quantityChange INT           NOT NULL,
    timestamp      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    remarks        VARCHAR(255),
    FOREIGN KEY (itemId)  REFERENCES StockItem(itemId),
    FOREIGN KEY (userId)  REFERENCES User(userId)
);

-- ── Customers & orders ──────────────────────────────────────
CREATE TABLE Customer (
    customerId    INT          AUTO_INCREMENT PRIMARY KEY,
    name          VARCHAR(100) NOT NULL,
    contactNumber VARCHAR(20),
    email         VARCHAR(150) UNIQUE,
    nicNumber     VARCHAR(12) UNIQUE,
    address       VARCHAR(255)
);

CREATE TABLE CustomerOrder (
    orderId   INT      AUTO_INCREMENT PRIMARY KEY,
    customerId INT     NOT NULL,
    orderDate  DATE    NOT NULL DEFAULT (CURRENT_DATE),
    status     ENUM('Pending','Confirmed','PartiallyShipped','Shipped','Cancelled') NOT NULL DEFAULT 'Pending',
    deliveryAddress VARCHAR(255),
    FOREIGN KEY (customerId) REFERENCES Customer(customerId)
);

CREATE TABLE Payment (
    paymentId   INT           AUTO_INCREMENT PRIMARY KEY,
    orderId     INT           NOT NULL,
    amount      DECIMAL(12,2) NOT NULL CHECK (amount > 0),
    paymentDate DATE          NOT NULL DEFAULT (CURRENT_DATE),
    FOREIGN KEY (orderId) REFERENCES CustomerOrder(orderId)
);

CREATE TABLE Reservation (
    reservationId    INT  AUTO_INCREMENT PRIMARY KEY,
    orderId          INT  NOT NULL,
    itemId           INT  NOT NULL,
    reservedQuantity INT  NOT NULL CHECK (reservedQuantity > 0),
    returnedQuantity INT  NOT NULL DEFAULT 0 CHECK (returnedQuantity >= 0),   -- added: running total of returned units
    status           ENUM('Active','Fulfilled','Cancelled') NOT NULL DEFAULT 'Active',
    FOREIGN KEY (orderId) REFERENCES CustomerOrder(orderId),
    FOREIGN KEY (itemId)  REFERENCES StockItem(itemId)
);

-- Added: money paid back to a customer (order cancelled, or goods returned)
CREATE TABLE Refund (
    refundId    INT           AUTO_INCREMENT PRIMARY KEY,
    orderId     INT           NOT NULL,
    amount      DECIMAL(12,2) NOT NULL CHECK (amount > 0),
    refundDate  DATE          NOT NULL DEFAULT (CURRENT_DATE),
    reason      ENUM('OrderCancelled','GoodsReturned') NOT NULL,
    processedBy INT           NOT NULL,
    FOREIGN KEY (orderId)     REFERENCES CustomerOrder(orderId),
    FOREIGN KEY (processedBy) REFERENCES User(userId)
);

-- ── Notifications ───────────────────────────────────────────
CREATE TABLE Notification (
    notificationId INT          AUTO_INCREMENT PRIMARY KEY,
    userId         INT          NOT NULL,
    message        TEXT         NOT NULL,
    timestamp      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    isRead         BOOLEAN      NOT NULL DEFAULT FALSE,
    FOREIGN KEY (userId) REFERENCES User(userId)
);

CREATE TABLE Report (
    reportId       INT         AUTO_INCREMENT PRIMARY KEY,
    generatedBy    INT         NOT NULL,
    type           VARCHAR(80) NOT NULL,
    dateRangeStart DATE        NOT NULL,
    dateRangeEnd   DATE        NOT NULL,
    generatedAt    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    content        LONGTEXT    NULL,           -- the full text of the report, so it can be opened again
    FOREIGN KEY (generatedBy) REFERENCES User(userId)
);



